<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Ostatnio odwiedzane';?>
<div class="page-head"><div><p class="eyebrow">Historia</p><h1>Ostatnio odwiedzane</h1><p class="muted">Ostatnie strony widoczne dla Twojego konta.</p></div><?php if($items):?><form method="post" action="<?=Html::e(Url::to('/recent/clear'))?>" onsubmit="return confirm('Wyczyścić własną historię odwiedzin?')"><?=Csrf::field()?><button class="button secondary">Wyczyść historię</button></form><?php endif;?></div>
<section class="card section-card"><?php if(!$items):?><div class="empty-state"><p class="muted">Brak historii odwiedzin.</p></div><?php endif;?><?php foreach($items as $item):?><a class="list-row" href="<?=Html::e(Url::to('/pages/'.$item['id']))?>"><span><strong><?=Html::e($item['title'])?></strong><small><?=Html::e($item['space_name'])?></small></span><time><?=Html::e($item['viewed_at'])?></time></a><?php endforeach;?></section>
